"""Нулевое доверие, сегментация IT/OT, реагирование на инцидент и политика аутентификации на уровне lead.
Сценарий с ограничениями → пары «тема: верное / неверное» (в экземпляр из пары берётся одно утверждение) + два непарных
неверных; у каждого сценария своё пояснение. Обозначения разделов и категорий — только в пояснении, чтобы не подсказывать
ответ; неверные варианты несут конкретику с неверными значениями и сопоставимы по длине с верными.
Сверено: NIST SP 800-207 (разд. 2.1 принципы 2, 3, 4, 6; 3 — PE/PA/PEP; 3.1.2 микросегментация; 7.2 гибридный режим);
NIST SP 800-61r3, апрель 2025 (RS.MI — критерии сдерживания и песочница, RS.MI-01, RS.AN-07 — данные инцидента как
доказательства, RC.RP-01 — восстановление во время реагирования, RC.RP-03 — проверка копий, ID.IM — улучшения);
CISA #StopRansomware Guide, чек-лист реагирования (изоляция на уровне коммутатора, выключение — только если нельзя
отключить от сети, образ и дамп памяти); NIST SP 800-82r3, сентябрь 2023 (разд. 5: DMZ без прямого трафика, исходящие
правила не слабее входящих, MFA для удалённого доступа, патчи после полевых испытаний; E.1.2 однонаправленные шлюзы;
компенсирующие меры для устройств без антивируса); NIST SP 800-63B-4, август 2025 (PSTN — restricted, AAL2 — обязателен
вариант с устойчивостью к фишингу, OTP к фишингу не устойчивы, AAL3 — аппаратный неэкспортируемый ключ, запрет
периодической смены паролей)."""
from __future__ import annotations
import random
from ..base import template, Instance, shuffle_options
from ..common import _run_python, _sql_eval, _sql_block, _choice, _multi


@template("gen_security_lead_zerotrust_ir", title="Сегментация, нулевое доверие и реагирование на инцидент",
          competency="ИБ: модель угроз, сегментация, нулевое доверие, реагирование",
          specializations=["security"], technologies=["security_basics", "networking"],
          fmt="multichoice", grade_level="lead", difficulty_shift=0.2)
def _lead_zerotrust_ir(rng: random.Random) -> Instance:
    org = rng.choice(["сети клиник", "регионального банка", "производственного холдинга", "логистической компании", "телеком-оператора"])
    seg = rng.choice(["отдела продаж", "бухгалтерии", "филиала", "конструкторского бюро"])
    ot = rng.choice(["котельная", "линия розлива", "подстанция", "цех сборки"])
    months = rng.choice([9, 12, 18])
    hours = rng.choice([4, 8, 12])
    legacy = rng.choice([7, 12, 20])
    admins = rng.choice([30, 40, 60])
    scenario = rng.randrange(4)

    if scenario == 0:
        q = (f"У {org} плоская сеть, {legacy} устаревших систем без поддержки агентов и MFA, на переход к нулевому доверию дано "
             f"{months} месяцев при ограниченном бюджете. Какие решения соответствуют NIST SP 800-207? Выберите все подходящие.")
        pairs = [
            ("Мигрировать по одному бизнес-процессу; длительное сосуществование ZTA-сегментов с периметровыми — ожидаемый гибридный режим, а не провал проекта",
             "Мигрировать всю сеть за один цикл обновления, выводя периметровые средства (межсетевые экраны, VPN) из эксплуатации: их сохранение противоречит модели"),
            ("Для устаревших систем без агентов применим подход микросегментации: шлюз (NGFW, коммутатор) выступает точкой применения политики перед группой ресурсов",
             "Для устаревших систем без агентов подхода нет: ZTA строится только на агенте на каждом хосте, такие системы из архитектуры исключают"),
            ("Доступ выдаётся на сеанс к конкретному ресурсу с минимальными привилегиями; допуск к одному ресурсу не даёт автоматически доступа к другому",
             "Доступ выдаётся на рабочую смену после проверки устройства при подключении к сегменту и распространяется на все ресурсы этого сегмента"),
            ("Решение о доступе принимает policy engine по динамической политике (идентичность, состояние устройства, поведение, среда); точка применения лишь исполняет его",
             "Решение о доступе принимает точка применения по статическому списку «сеть источника → разрешённые порты», который пересматривают раз в квартал"),
        ]
        extra = [
            "VLAN-сегментация с межсегментным фильтром уже является реализацией нулевого доверия: проверка идентичности и состояния устройства — необязательное дополнение",
            "MFA в ZTA нужна только внешним пользователям и подрядчикам: внутренние учётные записи подтверждаются сетевым адресом и доменным входом",
        ]
        expl = ("SP 800-207: миграция по одному процессу и гибридный режим (7.2); микросегментация со шлюзом-PEP для систем без агента (3.1.2); "
                "доступ на сеанс с минимальными привилегиями без «наследования» (принцип 3); динамическая политика и PE/PA/PEP (принцип 4, разд. 3). "
                "Сетевое расположение доверия не даёт (принцип 2), MFA — часть ICAM для доступа к ресурсам (принцип 6).")
    elif scenario == 1:
        q = (f"У {org} шифровальщик поразил файловые серверы {seg}; бизнес требует вернуть сервис за {hours} часов, юристы — сохранить "
             f"доказательства, резервные копии есть. Какие действия соответствуют NIST SP 800-61r3 и чек-листу CISA? Выберите все подходящие.")
        pairs = [
            ("Сдерживание: отключить поражённые системы от сети (при массовом поражении — на уровне коммутатора); выключать питание только если отключить от сети нельзя",
             "Сдерживание: первым делом выключить питание всех поражённых машин — так остановка шифрования надёжнее, а образ диска снимут позже"),
            ("До восстановления проверить резервные копии и среду восстановления на индикаторы компрометации и повреждения: восстановление из заражённой копии вернёт атакующего",
             "Восстанавливать из самой свежей копии без проверки: чем она новее, тем меньше потери, а проверку целостности делают при разборе инцидента"),
            ("Снять образ диска и дамп памяти с выборки поражённых машин до лечения: собранные данные — доказательства, даже если до суда не дойдёт",
             "Снимать образы и дампы памяти только при полной процедуре chain of custody: без неё собранные журналы доказательствами не считаются"),
            ("Критерии выбора мер сдерживания готовят заранее с учётом типа инцидента и срока действия меры: аварийный обход на часы, временный — на недели, постоянное решение",
             "Перенаправить атакующего в песочницу для сбора доказательств — стандартный первый шаг сдерживания, который не требует согласования с юристами"),
        ]
        extra = [
            "Восстановление сервиса начинают только после полного завершения расследования: параллельное восстановление стандарт запрещает",
            f"После восстановления серверов {seg} из копии инцидент закрыт: разбор с извлечением уроков проводят только при нарушении SLA",
        ]
        expl = ("CISA: изоляция от сети, выключение — только если изолировать нельзя; образ и дамп памяти до лечения. SP 800-61r3: копии "
                "проверяют на индикаторы компрометации до восстановления (RC.RP-03); данные инцидента — доказательства и без формального "
                "chain of custody (RS.AN-07); критерии сдерживания с учётом срока действия меры готовят заранее, песочница — только после "
                "согласования с юристами (RS.MI); восстановление может идти параллельно реагированию (RC.RP-01); улучшения — ID.IM.")
    elif scenario == 2:
        q = (f"У {org} есть OT-сеть ({ot}): нужна телеметрия в IT-аналитику, подрядчику — удалённое обслуживание контроллеров; бюджет на "
             f"однонаправленный шлюз ограничен. Какие решения соответствуют NIST SP 800-82r3? Выберите все подходящие.")
        pairs = [
            ("Между корпоративной и OT-сетью ставят DMZ: прямой трафик между ними запрещён, обмен идёт только через сервисы DMZ, которые отдельно мониторят",
             "Между корпоративной и OT-сетью достаточно межсетевого экрана с разрешёнными портами; DMZ нужна только при выходе OT-сети в интернет"),
            ("Однонаправленный шлюз (data diode) аппаратно пропускает данные только в одну сторону — подходит для телеметрии OT → IT, но управлять через него из IT невозможно в принципе",
             "Однонаправленный шлюз (data diode) можно перенастроить на двусторонний обмен на время сеанса обслуживания, как межсетевой экран с временным правилом"),
            ("Исходящие правила из OT делают такими же строгими, как входящие: неуправляемые исходящие соединения с нижних уровней — значимый риск",
             "Исходящий трафик из OT в IT не фильтруют: угроза идёт только снаружи внутрь, а строгие исходящие правила ломают телеметрию"),
            ("Удалённый доступ подрядчика к OT — только с многофакторной аутентификацией и через сервисы DMZ, а не прямым туннелем в сеть управления",
             "VPN подрядчика терминируют прямо в сети управления с парольным входом, чтобы не держать лишний сервер в DMZ и не ждать второй фактор"),
        ]
        extra = [
            "Патчи на OT-компоненты ставят сразу по выходу, как в IT: отложенное на полевые испытания обновление стандарт считает недопустимым",
            "Если для контроллеров нет антивируса, требование защиты от вредоносного кода к ним не применяется, и компенсирующих мер стандарт не требует",
        ]
        expl = ("SP 800-82r3: DMZ между корпоративной и OT-сетью без прямого трафика; исходящие правила не слабее входящих; data diode — "
                "аппаратно одностороннее устройство (E.1.2); MFA для удалённого доступа к OT. Патчи ставят после испытаний в полевых условиях, "
                "для устройств без антивируса нужны компенсирующие меры (например, межсетевой экран с глубокой инспекцией пакетов).")
    else:
        q = (f"У {org} доступ к продакшну имеют {admins} инженеров и подрядчики; второй фактор сейчас — SMS, бюджет на аппаратные ключи "
             f"покрывает треть людей. Какие решения соответствуют NIST SP 800-63B-4? Выберите все подходящие.")
        pairs = [
            ("Коды по SMS и голосу (PSTN out-of-band) имеют статус restricted: допустимы с оговорками, но для привилегированного доступа их планово заменяют устойчивыми к фишингу аутентификаторами",
             f"Коды по SMS и голосу (PSTN out-of-band) полностью запрещены для AAL2 с августа 2025 года, поэтому всех {admins} инженеров нужно немедленно перевести на аппаратные ключи"),
            ("AAL3 требует криптографический аутентификатор с неэкспортируемым ключом в защищённой аппаратной среде и устойчивость к фишингу — ключи выдают в первую очередь учётным записям с административными правами",
             "AAL3 достигается программным TOTP-приложением на смартфоне с включённой блокировкой экрана, поэтому аппаратные ключи можно не покупать вовсе"),
            ("Периодическую смену паролей требовать нельзя; смена обязательна при признаках компрометации",
             "Ротация паролей каждые 90 дней — требование для привилегированных учётных записей, а смена при компрометации — на усмотрение владельца"),
            ("На AAL2 верификатор обязан предлагать хотя бы один устойчивый к фишингу вариант аутентификации",
             "На AAL2 устойчивость к фишингу не рассматривается — это требование только AAL3, поэтому на AAL2 достаточно пароля и одноразового кода"),
        ]
        extra = [
            "Одноразовые коды из TOTP-приложения считаются устойчивыми к фишингу, поэтому закрывают требование AAL2 о таком варианте",
            "Подключение из офисной сети может заменять второй фактор для внутренних ресурсов: сетевое расположение — допустимый атрибут доверия",
        ]
        expl = ("SP 800-63B-4: PSTN — restricted, а не запрещён; AAL3 — аппаратный неэкспортируемый ключ с устойчивостью к фишингу; на AAL2 "
                "обязателен хотя бы один устойчивый к фишингу вариант, а одноразовые коды (OTP, out-of-band) к фишингу не устойчивы (3.2.5); "
                "периодическая смена паролей запрещена (SHALL NOT), смена — при компрометации. Сетевое расположение по SP 800-207 доверия не даёт.")

    rng.shuffle(pairs)
    k = rng.randint(2, 3)
    correct = [p[0] for p in pairs[:k]]
    wrong = [p[1] for p in pairs[k:]] + extra
    return _multi(rng, q, correct, wrong, expl)
